  assert.deepEqual(readdirSync(root).filter((name) => name.startsWith("adapter-state.json.bak-")), [],
    "公开读取 helper 不产生隔离备份（保持既有无副作用语义）");

  // 合法映射 + null 显式清空 + 各非法形态逐个区分
  writeFileSync(join(root, "adapter-state.json"), JSON.stringify({
    p1: "a",
    p2: null,
    p3: "",
    p4: 42,
    p5: ["a"],
    p6: {},
