  // 单一扰动区间下无可计账区间 → 消费未知（比强行声称 ≈0 更诚实）
  assert.ok(panel.includes("— 消费未知"), "无可计区间时徽章显示消费未知");
  assert.ok(panel.includes("另有充值 +¥45.62"), "徽章 title 注明未计入的充值额");
}

// ================================================================ A2 opencode-go 空 data 防御回归

{
  const html = openCodeGoAdapter.formatCapsule({
    time: Date.now(),
    data: {},
    status: "stale",
