console.error("EVAL-ORDER-TAG: V1");
import {
  ADAPTER_CONTRACT_VERSION_V1,
  isHostProviderAdapter,
  describeAdapterShape,
  isClientProviderRenderer,
  defineUsageAdapter,
  usageError,
  usageOk,
  openCodeGoAdapter,
  esc,
  parseUsageResponse,
