// ---------------------------------------------------------------- defineUsageAdapter

{
  const adapter = defineUsageAdapter({
    id: "my-test",
    label: "My Test",
    providers: ["openai"],
    windows: [
      { key: "rolling", name: "5h 滚动", limit: 12 },
