  assert.ok(svg.includes('stroke-dasharray:4 3;stroke-opacity:.65'), "100% 参考线虚线样式");
  assert.ok(svg.includes('font-size:9px">100%</text>'),
    "lo<=100<=hi 时绘制 100% 配额参考线（与 y 轴 9.5px 刻度字号区分）");
}
{
  // hi < 100：无参考线；刻度出现小数格式
