  });
  assert.ok(!svg.includes(">100%</text>"), "hi<100 无 100% 参考线");
  assert.ok(svg.includes(">0.5%</text>"), "非整数刻度保留一位小数");
}
{
  // 重置线：resetsAt 落在采样区间内
