// ---------------------------------------------------------------- resetTicks 回溯与非法输入边界（#150 变异加固，经 miniChartSvgMarkup 观测）

/** 提取 SVG 中窗口重置竖线的 x1 坐标序列 */
function resetLineXs(svg) {
  return [...svg.matchAll(/<line x1="([\d.]+)" y1="14"[^]*?<title>窗口重置点<\/title>/g)]
    .map((m) => Number(m[1]));
}

{
